def forward(groups):
    date, space, time = groups
    dt = datetime.strptime(f"20{date} {time}", "%Y/%m/%d %H:%M:%S")
    return {'stored': [int(dt.timestamp() * 1000)], 'layout': [len(space)]}

def inverse(record):
    timestamp = int(record['stored'][0])
    space_length = record['layout'][0]
    dt = datetime.fromtimestamp(timestamp / 1000)
    return dt.strftime('%y/%m/%d') + (' ' * space_length) + dt.strftime('%H:%M:%S')
